# Deploys app.service acme::trips::Trips.web to one environment, from the model:
#   1. builds it (`pnpm build`, skipped with --no-build),
#   2. copies its secrets from the vault (deploy/cloudflare/sync-secrets.sh, skipped with --no-secrets),
#   3. runs `wrangler deploy` with the environment's block of wrangler.jsonc.
#
# Needs: what deploy/cloudflare/wrangler.sh needs.
#
#   bash deploy/cloudflare/deploy.sh <environment> [--no-build] [--no-secrets]
set -euo pipefail
cd "$(dirname "$0")/../.."

ENVIRONMENT="${1:-}"
BUILD=1; SECRETS=1
for arg in "${@:2}"; do
  case "$arg" in
    --no-build) BUILD=0 ;;
    --no-secrets) SECRETS=0 ;;
    *) echo 'usage: bash deploy/cloudflare/deploy.sh <environment> [--no-build] [--no-secrets]' >&2; exit 2 ;;
  esac
done
case "$ENVIRONMENT" in production) ;; *) echo 'usage: bash deploy/cloudflare/deploy.sh <environment> [--no-build] [--no-secrets] (environments: production)' >&2; exit 2 ;; esac

if [ "$BUILD" = 1 ]; then
