  pnpm build
fi
if [ "$SECRETS" = 1 ]; then bash deploy/cloudflare/sync-secrets.sh "$ENVIRONMENT"; fi

case "$ENVIRONMENT" in
  production)
    bash deploy/cloudflare/wrangler.sh "$ENVIRONMENT" deploy --config wrangler.jsonc
    ;;
  *) echo 'usage: bash deploy/cloudflare/deploy.sh <environment> [--no-build] [--no-secrets] (environments: production)' >&2; exit 2 ;;
esac
